/**
 * Per-activity split / running-dynamics data generated by
 * `run_page/gen_splits.py` into `public/splits/{run_id}.json`.
 * Everything is optional: older runs, GPX/TCX imports or devices without
 * running dynamics simply have no file or null fields.
 */

type N = number | null;

export interface SplitRow {
  index: number;
  distance: N;
  time: N;
  pace: N; // seconds per km
  speed: N; // m/s
  hr_avg: N;
  hr_max: N;
  cadence_avg: N; // steps per minute
  cadence_max: N;
  stride_length: N; // m
  power_avg: N;
  power_max: N;
  normalized_power?: N;
  elev_gain: N;
  elev_loss: N;
  vertical_oscillation: N; // cm
  ground_contact_time: N; // ms
  gct_balance: N; // left %
  vertical_ratio: N; // %
  temperature: N;
  respiration_rate?: N;
  calories?: N;
  intensity?: string | null;
  trigger?: string | null;
  partial?: boolean;
}

export interface RunSummary extends Omit<SplitRow, 'index'> {
  elapsed_time: N;
  moving_time: N;
  best_pace: N;
  aerobic_te: N;
  anaerobic_te: N;
  training_load: N;
  training_stress_score: N;
  intensity_factor: N;
  vo2max: N;
  temperature_min: N;
  temperature_max: N;
  temperature_source?: 'weather' | 'device' | null;
  steps: N;
  rpe: N;
  feel: N;
}

export interface ZoneInfo {
  seconds: number[];
  high_boundary: (number | null)[] | null;
  calc_type?: string | null;
  max_hr?: N;
  resting_hr?: N;
  threshold_hr?: N;
  threshold_pace?: N; // s/km
  ftp?: N;
}

export interface RunChart {
  d: number[]; // km
  t?: number[]; // seconds from activity start (timer time)
  pace?: N[];
  hr?: N[];
  cad?: N[];
  power?: N[];
  alt?: N[];
  gct?: N[];
  vo?: N[];
  vr?: N[]; // vertical ratio %
  temp?: N[];
}

export interface RunSplits {
  version: number;
  run_id: number;
  sport: string;
  sub_sport: string | null;
  device: string | null;
  /** FIT file_id.manufacturer (e.g. garmin) — hardware brand, not sync source. */
  manufacturer?: string | null;
  /** File kind for GPX/TCX imports; FIT analyzer may omit. */
  source?: string | null;
  summary: RunSummary;
  zones: { hr?: ZoneInfo; power?: ZoneInfo; pace?: ZoneInfo } | null;
  splits: SplitRow[];
  laps: SplitRow[];
  chart: RunChart | null;
}

const BASE = `${(import.meta.env.BASE_URL || '/').replace(/\/?$/, '/')}splits/`;

let indexPromise: Promise<Set<number>> | null = null;
const filePromises = new Map<number, Promise<RunSplits | null>>();

async function fetchJson(url: string): Promise<unknown> {
  const res = await fetch(url);
  if (!res.ok) return null;
  // Dev servers answer unknown paths with index.html; treat that as missing.
  const type = res.headers.get('content-type') || '';
  if (type.includes('text/html')) return null;
  return res.json();
}

/** Ids that have a splits file. Never rejects. */
export function loadSplitsIndex(): Promise<Set<number>> {
  indexPromise ??= fetchJson(`${BASE}index.json`)
    .then((ids) => new Set(Array.isArray(ids) ? ids.map((x) => Number(x)) : []))
    .catch(() => new Set<number>());
  return indexPromise;
}

/** Splits for one run, or null when not generated. Never rejects. */
export function loadSplits(runId: number): Promise<RunSplits | null> {
  let p = filePromises.get(runId);
  if (!p) {
    p = loadSplitsIndex()
      .then((ids) =>
        ids.has(runId) ? fetchJson(`${BASE}${runId}.json`) : null
      )
      .then((d) => (d && typeof d === 'object' ? (d as RunSplits) : null))
      .catch(() => null);
    filePromises.set(runId, p);
  }
  return p;
}

/** "4'05\"" from seconds per km. */
export function formatPaceSeconds(sec: N | undefined): string {
  if (sec == null || !Number.isFinite(sec) || sec <= 0 || sec > 3600)
    return '--';
  const s = Math.round(sec);
  return `${Math.floor(s / 60)}'${String(s % 60).padStart(2, '0')}"`;
}

/** "1:02:03" / "42:10" from seconds. */
export function formatClock(sec: N | undefined): string {
  if (sec == null || !Number.isFinite(sec)) return '--';
  const s = Math.round(sec);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const r = String(s % 60).padStart(2, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${r}` : `${m}:${r}`;
}

/** Garmin-like 5 zones from threshold pace (s/km). Faster → higher zone. */
const PACE_LTP_FACTORS = [1.29, 1.14, 1.06, 0.99];
const PACE_FIXED_BOUNDS = [540, 480, 420, 360];

export function thresholdPaceFromVo2max(vo2: N | undefined): number | null {
  if (vo2 == null || !Number.isFinite(vo2) || vo2 < 20 || vo2 > 95) return null;
  const vMMin = (vo2 - 3.5) / 0.2;
  if (vMMin <= 0) return null;
  const vLtp = (vMMin / 60) * 0.88;
  if (vLtp <= 0) return null;
  return 1000 / vLtp;
}

/**
 * Time-weighted pace zones from the downsampled chart.
 * Must use `t` deltas — counting points as seconds is the production bug
 * (101 points → 1:41 instead of ~34:11).
 */
export function paceZonesFromChart(
  pace: (number | null)[] | undefined,
  t?: number[],
  thresholdPace?: number | null
): ZoneInfo | null {
  if (!pace || !t || t.length !== pace.length || pace.length < 2) return null;
  const ltp =
    thresholdPace != null && Number.isFinite(thresholdPace) && thresholdPace > 0
      ? thresholdPace
      : null;
  const bounds = ltp ? PACE_LTP_FACTORS.map((f) => ltp * f) : PACE_FIXED_BOUNDS;
  const secs = Array.from({ length: bounds.length + 1 }, () => 0);
  for (let i = 0; i < pace.length; i++) {
    const p = pace[i];
    if (p == null || !Number.isFinite(p) || p <= 0) continue;
    const dt = i + 1 < t.length ? t[i + 1] - t[i] : i > 0 ? t[i] - t[i - 1] : 0;
    if (dt <= 0 || dt > 120) continue;
    let z = bounds.length;
    for (let b = 0; b < bounds.length; b++) {
      if (p > bounds[b]) {
        z = b;
        break;
      }
    }
    secs[z] += dt;
  }
  const total = secs.reduce((a, b) => a + b, 0);
  if (total < 30) return null;
  return {
    seconds: secs.map((s) => Math.round(s)),
    high_boundary: [...bounds, null],
    calc_type: ltp
      ? 'percent_threshold_pace_estimated'
      : 'fixed_pace_estimated',
    threshold_pace: ltp,
  };
}

/** Pace bounds are s/km; show `5'00"–6'00" /km`, never raw `300 /km`. */

/** Joyrun-style fixed cadence bands (steps/min). Higher cadence → higher zone. */
const CADENCE_BOUNDS = [153, 164, 174, 184] as const;

export function cadenceZoneLabels(): string[] {
  return ['<153', '153–163', '164–173', '174–183', '>183'];
}

/**
 * Time-weighted cadence zones from the downsampled chart (same dt rules as pace).
 */
export function cadenceZonesFromChart(
  cad: (number | null)[] | undefined,
  t?: number[]
): ZoneInfo | null {
  if (!cad || !t || t.length !== cad.length || cad.length < 2) return null;
  const secs = Array.from({ length: CADENCE_BOUNDS.length + 1 }, () => 0);
  for (let i = 0; i < cad.length; i++) {
    const c = cad[i];
    if (c == null || !Number.isFinite(c) || c <= 0 || c > 220) continue;
    const dt = i + 1 < t.length ? t[i + 1] - t[i] : i > 0 ? t[i] - t[i - 1] : 0;
    if (dt <= 0 || dt > 120) continue;
    let z: number = CADENCE_BOUNDS.length;
    for (let b = 0; b < CADENCE_BOUNDS.length; b++) {
      if (c < CADENCE_BOUNDS[b]) {
        z = b;
        break;
      }
    }
    secs[z] += dt;
  }
  const total = secs.reduce((a, b) => a + b, 0);
  if (total < 30) return null;
  return {
    seconds: secs.map((s) => Math.round(s)),
    // Labels are provided by the UI; bounds only drive binning above.
    high_boundary: null,
    calc_type: 'fixed_cadence_estimated',
  };
}

export function formatPaceZoneRange(
  lo: number | null | undefined,
  hi: number | null | undefined,
  i: number
): string {
  const loP = formatPaceSeconds(lo);
  const hiP = formatPaceSeconds(hi);
  let core = '';
  if (i === 0) core = hiP !== '--' ? `> ${hiP}` : '';
  else if (hiP !== '--' && loP !== '--') core = `${hiP}–${loP}`;
  else if (loP !== '--') core = `< ${loP}`;
  return core ? `${core} /km` : '';
}
